INSERT INTO nhat_ky_tu_van (ma_sv, ma_cvht, id_canh_bao, ngay_tu_van, hinh_thuc, noi_dung, nguyen_nhan, giai_phap, cam_ket_sinh_vien) VALUES ('20250006', 'CV001', 3, '2026-08-25', 'Gặp trực tiếp tại Văn phòng Khoa', 'Cố vấn học tập đã làm việc với sinh viên Hoàng Hải Hiền về kết quả học tập và cảnh báo học vụ MUC_3. Rà soát bảng điểm các học phần bị nợ (13 tín chỉ).', 'Sinh viên đi làm thêm nhiều ca đêm, phân bổ thời gian tự học chưa hợp lý, vắng một số buổi lý thuyết trọng tâm.', 'Rút bớt 2 môn khó học kỳ tới để tập trung trả nợ 2 môn tiên quyết. Đăng ký tham gia nhóm hỗ trợ học tập của Khoa. Giảm giờ làm thêm.', 'Sinh viên cam kết tham gia đầy đủ >= 90% các buổi học trên lớp, đạt GPA học kỳ tới >= 2.3 và tích lũy thêm tối thiểu 14 tín chỉ.');
