INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('TB-BC-001', '📢 Thông báo Đăng ký Học phần & Kế hoạch Khung Đào tạo 150 Tín chỉ', 'Kính gửi toàn thể sinh viên Trường Đại học Công nghệ Đông Á (EAUT),
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('TB-BC-002', '⚠️ Thông báo Quy chế Điểm danh & Ngưỡng Cấm thi Học phần (Vắng >= 20%)', 'Căn cứ Quy chế đào tạo đại học tín chỉ: Sinh viên nghỉ học quá 20% tổng số tiết (tương đương từ 3-4 buổi tùy học phần) sẽ bị CẤM THI kết thúc học phần. Hệ thống sẽ tự động gửi cảnh báo khi sinh viên nghỉ 2 buổi.', 'ALL', 'ALL', NULL, '2026-08-20 09:00:00', 'Phòng Đào tạo & Khảo thí', 400, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('TB-BC-003', '🎓 Thông báo Xét Điều kiện Giao Đề tài Đồ án Tốt nghiệp Kỹ sư (Khóa K12 & K11)', 'Điều kiện nhận ĐATN 10 tín chỉ: Sinh viên Năm 4/Năm 5 tích lũy tối thiểu 125/150 tín chỉ, CPA >= 2.0 và không vi phạm quy chế đào tạo. Các trường hợp đạt <= 120 tín chỉ phải đăng ký học trả nợ trước.', 'TIER_3', 'ALL', NULL, '2026-08-25 10:00:00', 'Khoa Công nghệ Thông tin', 45, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('CHAT-0001', 'Tin nhắn từ Võ Tuấn Tuấn', 'Em chào thầy Phong ạ! Thầy ơi cho em hỏi về lịch học bổ sung học phần Lập trình Java với ạ.', 'CHAT', 'DCCTPM15A', '20250001', '2026-08-26 14:15:00', 'Võ Tuấn Tuấn (20250001)', 1, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('CHAT-0002', 'Phản hồi từ Cố vấn học tập', 'Chào em! Lịch học bổ sung sẽ bắt đầu vào tuần thứ 3 của học kỳ, em nhớ kiểm tra thời khóa biểu trên hệ thống nhé!', 'CHAT', 'DCCTPM15A', '20250001', '2026-08-26 14:18:00', 'TS. Đinh Văn Phong (Cố vấn học tập)', 1, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('CHAT-0003', 'Tin nhắn từ Võ Tuấn Tuấn', 'Dạ vâng em cảm ơn thầy nhiều ạ!', 'CHAT', 'DCCTPM15A', '20250001', '2026-08-26 14:20:00', 'Võ Tuấn Tuấn (20250001)', 1, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('CHAT-0004', 'Tin nhắn từ Nguyễn Ngọc Anh', 'Thầy ơi em nhận được thông báo cảnh báo đã nghỉ 2 buổi môn Cấu trúc dữ liệu. Em lo quá thầy ạ!', 'CHAT', 'DCCTPM15B', '20250021', '2026-08-28 09:10:00', 'Nguyễn Ngọc Anh (20250021)', 1, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('CHAT-0005', 'Phản hồi từ Cố vấn học tập', 'Chào em! Môn này có tổng 15 buổi, ngưỡng vắng tối đa là 3 buổi (20%). Em đã nghỉ 2 buổi rồi nên tuyệt đối không được nghỉ thêm buổi nào nữa nhé!', 'CHAT', 'DCCTPM15B', '20250021', '2026-08-28 09:15:00', 'TS. Đinh Văn Phong (Cố vấn học tập)', 1, 'DA_GUI');
INSERT INTO thong_bao (ma_thong_bao, tieu_de, noi_dung, nhom_rui_ro, ma_lop, ma_sv, ngay_gui, nguoi_gui, so_luong_nhan, trang_thai) VALUES ('CHAT-0006', 'Tin nhắn từ Nguyễn Ngọc Anh', 'Dạ em hiểu rồi, em sẽ đi học đầy đủ các buổi còn lại ạ.', 'CHAT', 'DCCTPM15B', '20250021', '2026-08-28 09:18:00', 'Nguyễn Ngọc Anh (20250021)', 1, 'DA_GUI');
