-- ============================================================================
-- CSDL MYSQL QUẢN LÝ CỐ VẤN HỌC TẬP VÀ CẢNH BÁO HỌC VỤ (EAUT 5 NĂM ĐỒ SỘ)
-- Tương thích: MySQL Workbench, phpMyAdmin, XAMPP, MariaDB, Navicat
-- ============================================================================

CREATE DATABASE IF NOT EXISTS `ql_canhbao_hocvu` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `ql_canhbao_hocvu`;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `phien_dang_nhap`;
DROP TABLE IF EXISTS `nhat_ky_he_thong`;
DROP TABLE IF EXISTS `diem_danh`;
DROP TABLE IF EXISTS `chuyen_can_mon_hoc`;
DROP TABLE IF EXISTS `lich_giang_day`;
DROP TABLE IF EXISTS `thong_bao`;
DROP TABLE IF EXISTS `nhat_ky_tu_van`;
DROP TABLE IF EXISTS `canh_bao_hoc_vu`;
DROP TABLE IF EXISTS `ket_qua_hoc_tap`;
DROP TABLE IF EXISTS `sinh_vien`;
DROP TABLE IF EXISTS `lop_hoc`;
DROP TABLE IF EXISTS `mon_hoc`;
DROP TABLE IF EXISTS `co_van_hoc_tap`;
DROP TABLE IF EXISTS `tai_khoan`;
DROP TABLE IF EXISTS `vai_tro`;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE vai_tro (ma_vai_tro VARCHAR(20) PRIMARY KEY, ten_vai_tro VARCHAR(100) NOT NULL, mo_ta VARCHAR(255));
CREATE TABLE tai_khoan (id INT AUTO_INCREMENT PRIMARY KEY, ten_dang_nhap VARCHAR(50) UNIQUE NOT NULL, mat_khau VARCHAR(255) NOT NULL, ho_ten VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL, vai_tro VARCHAR(20) NOT NULL, ma_ref VARCHAR(20), ngay_tao DATETIME DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tk_vaitro FOREIGN KEY (vai_tro) REFERENCES vai_tro(ma_vai_tro));
CREATE TABLE co_van_hoc_tap (ma_cvht VARCHAR(20) PRIMARY KEY, ho_ten VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL, so_dien_thoai VARCHAR(20), khoa VARCHAR(100) NOT NULL);
CREATE TABLE mon_hoc (ma_mon VARCHAR(20) PRIMARY KEY, ten_mon VARCHAR(150) NOT NULL, so_tin_chi INT NOT NULL, so_tiet INT NOT NULL, so_buoi_toi_da_vang INT NOT NULL, khoa VARCHAR(100) NOT NULL);
CREATE TABLE lop_hoc (ma_lop VARCHAR(20) PRIMARY KEY, ten_lop VARCHAR(100) NOT NULL, khoa VARCHAR(100) NOT NULL, khoa_hoc INT NOT NULL, ma_cvht VARCHAR(20), CONSTRAINT fk_lop_covan FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht) ON DELETE SET NULL);
CREATE TABLE sinh_vien (ma_sv VARCHAR(20) PRIMARY KEY, ho_ten VARCHAR(100) NOT NULL, ngay_sinh DATE NOT NULL, gioi_tinh VARCHAR(10) NOT NULL, email VARCHAR(100) NOT NULL, so_dien_thoai VARCHAR(20), ma_lop VARCHAR(20) NOT NULL, trang_thai VARCHAR(30) DEFAULT 'DANG_HOC', tong_tin_chi_tich_luy INT DEFAULT 0, nam_thu INT DEFAULT 1, CONSTRAINT fk_sinhvien_lop FOREIGN KEY (ma_lop) REFERENCES lop_hoc(ma_lop) ON DELETE CASCADE);
CREATE TABLE ket_qua_hoc_tap (id INT AUTO_INCREMENT PRIMARY KEY, ma_sv VARCHAR(20) NOT NULL, hoc_ky INT NOT NULL, nam_hoc VARCHAR(20) NOT NULL, gpa_hoc_ky FLOAT NOT NULL, gpa_tich_luy FLOAT NOT NULL, so_tin_chi_no INT DEFAULT 0, tong_tin_chi_tich_luy INT DEFAULT 0, nam_thu INT DEFAULT 1, CONSTRAINT fk_kq_sinhvien FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE);
CREATE TABLE canh_bao_hoc_vu (id INT AUTO_INCREMENT PRIMARY KEY, ma_canh_bao VARCHAR(50) UNIQUE NOT NULL, ma_sv VARCHAR(20) NOT NULL, hoc_ky INT NOT NULL, nam_hoc VARCHAR(20) NOT NULL, muc_canh_bao VARCHAR(30) NOT NULL, gpa_xet_duyet FLOAT NOT NULL, ly_do VARCHAR(500), ngay_quyet_dinh DATE NOT NULL, trang_thai_tu_van VARCHAR(30) DEFAULT 'CHUA_TU_VAN', CONSTRAINT fk_canhbao_sinhvien FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE);
CREATE TABLE nhat_ky_tu_van (id INT AUTO_INCREMENT PRIMARY KEY, ma_sv VARCHAR(20) NOT NULL, ma_cvht VARCHAR(20) NOT NULL, id_canh_bao INT, ngay_tu_van DATE NOT NULL, hinh_thuc VARCHAR(100) NOT NULL, noi_dung LONGTEXT NOT NULL, nguyen_nhan LONGTEXT, giai_phap LONGTEXT, cam_ket_sinh_vien LONGTEXT, CONSTRAINT fk_nhatky_sinhvien FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE, CONSTRAINT fk_nhatky_covan FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht));
CREATE TABLE thong_bao (id INT AUTO_INCREMENT PRIMARY KEY, ma_thong_bao VARCHAR(50) UNIQUE NOT NULL, tieu_de VARCHAR(255) NOT NULL, noi_dung LONGTEXT NOT NULL, nhom_rui_ro VARCHAR(30) DEFAULT 'ALL', ma_lop VARCHAR(20) DEFAULT 'ALL', ma_sv VARCHAR(20), ngay_gui DATETIME DEFAULT CURRENT_TIMESTAMP, nguoi_gui VARCHAR(100), so_luong_nhan INT DEFAULT 0, trang_thai VARCHAR(30) DEFAULT 'DA_GUI');
CREATE TABLE lich_giang_day (id INT AUTO_INCREMENT PRIMARY KEY, ma_cvht VARCHAR(20) NOT NULL, ten_cvht VARCHAR(100) NOT NULL, ma_lop VARCHAR(20) NOT NULL, ten_lop VARCHAR(100) NOT NULL, tieu_de VARCHAR(200) NOT NULL, ngay DATE NOT NULL, gio_bat_dau VARCHAR(20) NOT NULL, gio_ket_thuc VARCHAR(20) NOT NULL, dia_diem VARCHAR(100) NOT NULL, hinh_thuc VARCHAR(50) DEFAULT 'TRUC_TIEP', loai_buoi VARCHAR(50) DEFAULT 'GIANG_DAY', trang_thai VARCHAR(30) DEFAULT 'SCHEDULED', ghi_chu LONGTEXT, CONSTRAINT fk_lich_cvht FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht), CONSTRAINT fk_lich_lop FOREIGN KEY (ma_lop) REFERENCES lop_hoc(ma_lop));
CREATE TABLE diem_danh (id INT AUTO_INCREMENT PRIMARY KEY, id_lich INT NOT NULL, ma_sv VARCHAR(20) NOT NULL, ngay_diem_danh DATE NOT NULL, trang_thai VARCHAR(30) DEFAULT 'CO_MAT', ghi_chu VARCHAR(255), CONSTRAINT fk_diemdanh_lich FOREIGN KEY (id_lich) REFERENCES lich_giang_day(id) ON DELETE CASCADE, CONSTRAINT fk_diemdanh_sv FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv));
CREATE TABLE chuyen_can_mon_hoc (id INT AUTO_INCREMENT PRIMARY KEY, ma_sv VARCHAR(20) NOT NULL, ma_mon VARCHAR(20) NOT NULL, ma_lop VARCHAR(20) NOT NULL, hoc_ky INT DEFAULT 1, nam_hoc VARCHAR(20) DEFAULT '2025-2026', tong_so_buoi INT DEFAULT 15, so_buoi_co_mat INT DEFAULT 15, so_buoi_muon INT DEFAULT 0, so_buoi_vang_phep INT DEFAULT 0, so_buoi_vang_khong_phep INT DEFAULT 0, tong_buoi_vang_quy_doi FLOAT DEFAULT 0.0, ty_le_vang FLOAT DEFAULT 0.0, diem_chuyen_can FLOAT DEFAULT 10.0, trang_thai_du_thi VARCHAR(30) DEFAULT 'DU_DIEU_KIEN', ly_do_cam_thi VARCHAR(500), ghi_chu VARCHAR(255), CONSTRAINT fk_cc_sv FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE, CONSTRAINT fk_cc_mon FOREIGN KEY (ma_mon) REFERENCES mon_hoc(ma_mon));
CREATE TABLE nhat_ky_he_thong (id INT AUTO_INCREMENT PRIMARY KEY, ten_dang_nhap VARCHAR(50) NOT NULL, ho_ten VARCHAR(100) NOT NULL, vai_tro VARCHAR(30) NOT NULL, loai_hanh_dong VARCHAR(50) NOT NULL, mo_ta_chi_tiet LONGTEXT NOT NULL, dia_chi_ip VARCHAR(50) DEFAULT '127.0.0.1', thiet_bi VARCHAR(100) DEFAULT 'Java Swing Desktop', thoi_gian DATETIME DEFAULT CURRENT_TIMESTAMP, trang_thai_phien VARCHAR(30) DEFAULT 'ONLINE');
CREATE TABLE phien_dang_nhap (id INT AUTO_INCREMENT PRIMARY KEY, ten_dang_nhap VARCHAR(50) UNIQUE NOT NULL, ho_ten VARCHAR(100) NOT NULL, vai_tro VARCHAR(30) NOT NULL, thoi_gian_dang_nhap DATETIME DEFAULT CURRENT_TIMESTAMP, thoi_gian_dang_xuat DATETIME, trang_thai VARCHAR(30) DEFAULT 'ONLINE', dia_chi_ip VARCHAR(50) DEFAULT '127.0.0.1', thiet_bi VARCHAR(100) DEFAULT 'Java Swing Desktop');
Nhà trường thông báo kế hoạch đăng ký học phần học kỳ mới theo chuẩn khung 150 tín chỉ. Đề nghị sinh viên các khóa K11 - K15 kiểm tra tiến độ tích lũy và liên hệ CVHT nếu gặp vướng mắc.', 'ALL', 'ALL', NULL, '2026-08-15 08:00:00', 'Phòng Quản lý Đào tạo EAUT', 400, 'DA_GUI');
